import sqlite3,time
c=sqlite3.connect('/app/oewn.sqlite')
qs={
'stats':'''SELECT s.wordid, COUNT(DISTINCT s.synsetid) a, COUNT(*) b, COUNT(DISTINCT syn.domainid) d, COUNT(DISTINCT syn.posid) p FROM senses s JOIN synsets syn ON syn.synsetid=s.synsetid GROUP BY s.wordid HAVING COUNT(DISTINCT syn.domainid)>=2''',
'stats_top':'''SELECT s.wordid, COUNT(DISTINCT s.synsetid) a, COUNT(*) b, COUNT(DISTINCT syn.domainid) d, COUNT(DISTINCT syn.posid) p FROM senses s JOIN synsets syn ON syn.synsetid=s.synsetid GROUP BY s.wordid HAVING COUNT(DISTINCT syn.domainid)>=2 ORDER BY b DESC,a DESC,d DESC,s.wordid LIMIT 500''',
'jointop':'''SELECT * FROM (SELECT s.wordid, COUNT(DISTINCT s.synsetid) a, COUNT(*) b, COUNT(DISTINCT syn.domainid) d, COUNT(DISTINCT syn.posid) p FROM senses s JOIN synsets syn ON syn.synsetid=s.synsetid GROUP BY s.wordid HAVING COUNT(DISTINCT syn.domainid)>=2) ORDER BY b DESC,a DESC,d DESC,wordid LIMIT 500''',
}
for n,q in qs.items():
    for i in range(3):
        t=time.time(); r=c.execute(q).fetchall(); print(n,i,round(time.time()-t,3),len(r))
